<main class="page-shell">
    <article class="facility-detail"><div class="facility-detail-hero"><?php if ($facility['image']): ?><img src="<?= e(media_url($facility['image'])) ?>" alt="<?= e($facility['image_alt'] ?: $facility['title']) ?>" width="900" height="500"><?php endif; ?><div><p class="eyebrow"><?= e($facility['category'] ?: 'Campus facility') ?></p><h1><?= e($facility['title']) ?></h1><p><?= e($facility['summary']) ?></p></div></div><div class="facility-detail-content"><?php if ($facility['description']): ?><div class="rich-content"><?= clean_html((string) $facility['description']) ?></div><?php endif; ?><dl><?php if ($facility['location']): ?><div><dt>Location</dt><dd><?= e($facility['location']) ?></dd></div><?php endif; ?><?php if ($facility['capacity']): ?><div><dt>Capacity</dt><dd><?= e($facility['capacity']) ?></dd></div><?php endif; ?><div><dt>Availability</dt><dd><?= e(ucwords(str_replace('_', ' ', $facility['availability_status']))) ?></dd></div></dl><?php if ($facility['equipment']): ?><h2>Equipment and facilities</h2><p><?= e($facility['equipment']) ?></p><?php endif; ?></div></article>
